class Solution:
    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:
        top, bottom = 0, len(matrix) - 1
        left, right = 0, len(matrix[0]) - 1
        out = []
        while top <= bottom and left <= right:
            out.extend(matrix[top][left:right + 1])              # top row
            out.extend(matrix[r][right] for r in range(top + 1, bottom + 1))   # right column
            if top < bottom:
                out.extend(matrix[bottom][c] for c in range(right - 1, left - 1, -1))   # bottom row
            if left < right:
                out.extend(matrix[r][left] for r in range(bottom - 1, top, -1))         # left column
            top, bottom, left, right = top + 1, bottom - 1, left + 1, right - 1
        return out
